import{_ as t,o as r,c as a,a5 as o}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Sequence Flow — View Workspace Members","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-18-view-workspace-members/sequence-flow.md","filePath":"feature/agency-workspace/3-4-18-view-workspace-members/sequence-flow.md"}'),s={name:"feature/agency-workspace/3-4-18-view-workspace-members/sequence-flow.md"};function i(l,e,c,n,d,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="sequence-flow-—-view-workspace-members" tabindex="-1">Sequence Flow — View Workspace Members <a class="header-anchor" href="#sequence-flow-—-view-workspace-members" aria-label="Permalink to &quot;Sequence Flow — View Workspace Members&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.18). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly. It does not restate business rules — see <code>spec.md</code> for those. &gt; &gt; Updated: 2026-09-23.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Client</strong> — an active member of the Workspace (MANAGER, CREATOR, CLIENT).</li><li><strong>System</strong> — the application service handling the request.</li><li><strong>Database</strong> — the persistent store holding Workspace, membership, user, and client profile records.</li></ul><hr><h2 id="flow-a-—-view-the-workspace-member-list" tabindex="-1">Flow A — View the Workspace member list <a class="header-anchor" href="#flow-a-—-view-the-workspace-member-list" aria-label="Permalink to &quot;Flow A — View the Workspace member list&quot;">​</a></h2><ol><li>Client → System: open <code>/workspaces/:id/members</code>.</li><li>System → Database: look up the Workspace by its identifier; a missing Workspace is rejected with 404 <code>WORKSPACE_NOT_FOUND</code>.</li><li>System → Database: read the caller&#39;s active membership row for that same Workspace; a missing row is rejected with 403 <code>WORKSPACE_ACCESS_DENIED</code>.</li><li>System → Database: read the Workspace&#39;s active membership rows.</li><li>System: collect the referenced user identifiers and load the matching user records.</li><li>System: collect the referenced client profile identifiers and load the matching client profiles.</li><li>System: map each membership to a member entry — taking the full name and email from the user record when one is linked, or the client profile display name with an empty email when the member was attached through a client profile.</li><li>System → Client: the member list — id, workspaceId, userId, fullName, email, clientProfileId, role, joinedAt, isActive.</li><li>Client: render the member table with each member&#39;s role.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>Status</th><th>Error code</th></tr></thead><tbody><tr><td>List members</td><td>Workspace does not exist</td><td>404</td><td><code>WORKSPACE_NOT_FOUND</code></td></tr><tr><td>List members</td><td>Caller is not an active member of that Workspace</td><td>403</td><td><code>WORKSPACE_ACCESS_DENIED</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The membership check is performed explicitly for the Workspace named in the request, rather than through a generic role check.</li><li>A member attached through a client profile has no linked user record, so the display name comes from the client profile and the email is empty.</li><li>The flow is read-only.</li></ul>',12)])])}const u=t(s,[["render",i]]);export{p as __pageData,u as default};
